    modulo1_l1_p_1: 'Cada mes, tu cuerpo pasa por 4 fases que afectan tu energía, concentración y estado de ánimo. No es capricho — es biología.',
    modulo1_l1_p_2: 'Cuando entiendes tu ciclo, puedes planificar mejor tu semana, negociar con más confianza y descansar sin culpa.',
    modulo1_l1_p_3: 'La fase menstrual (días 1-5) es tu momento de introspección. Tu energía es baja, pero tu intuición está en su máximo.',
    modulo1_l1_p_4: 'La fase folicular (días 6-13) es cuando tu energía sube. Es el momento ideal para empezar proyectos nuevos.',
    modulo1_l1_p_5: 'La fase ovulatoria (días 14-16) es tu punto más alto. Energía, confianza y comunicación en su máximo.',
