    modulo_video_fallback: 'Your browser does not support video.',
    modulo1_l1_h2_1: 'Your body isn\'t a machine — it\'s a cycle',
    modulo1_l1_h2_2: 'The 4 phases they didn\'t teach you in school',
    modulo1_l1_p_1: 'Every month, your body goes through 4 phases that affect your energy, focus and mood. It\'s not being fussy — it\'s biology.',
    modulo1_l1_p_2: 'When you understand your cycle, you can better plan your week, negotiate with more confidence and rest without guilt.',
    modulo1_l1_p_3: 'The menstrual phase (days 1-5) is your moment of introspection. Your energy is low, but your intuition is at its peak.',
    modulo1_l1_p_4: 'The follicular phase (days 6-13) is when your energy rises. It\'s the ideal time to start new projects.',
    modulo1_l1_p_5: 'The ovulatory phase (days 14-16) is your highest point. Energy, confidence and communication at their peak.',
    modulo1_l1_p_6: 'The luteal phase (days 17-28) is about preparation. Your body is getting ready, and your energy gradually decreases.',
    modulo1_l1_callout_intro_title: '🔬 What you\'ll learn in this module',
    modulo1_l1_callout_intro: 'Identify each phase of your cycle, know what type of work is ideal for each moment, and create a planning system that adapts to your body, not the other way around.',
    modulo1_l1_callout_1: '💡 Fact: Hormones don\'t just affect your uterus — they affect your brain, productivity and decision-making.',
    modulo1_l1_callout_2: '🎯 Action: Write down when your cycle starts this month and mark the phases on your calendar.',
    modulo1_l1_callout_3: '💡 Fact: Your energy, charisma and communication skills are at their peak during the ovulatory phase.',
    modulo1_l1_callout_4: '💡 Fact: The luteal phase is ideal for finishing pending tasks and organizing files.',
    modulo1_l1_phase_0_title: '🌑 Menstrual Phase — Your rest time',
    modulo1_l1_phase_1_title: '🌒 Follicular Phase — Your rising energy',
    modulo1_l1_phase_2_title: '🌕 Ovulatory Phase — Your peak moment',
    modulo1_l1_phase_3_title: '🌘 Luteal Phase — Your organizer mode',
    modulo1_l1_4fases_intro: 'Every month, your body goes through these 4 phases. Click on each one to learn more:',
    modulo1_phase_menstrual: 'Menstrual',modulo1_phase_menstrual_days: 'Days 1–5',
    modulo1_phase_folicular: 'Follicular',modulo1_phase_folicular_days: 'Days 6–13',
    modulo1_phase_ovulatoria: 'Ovulatory',modulo1_phase_ovulatoria_days: 'Days 14–17',
    modulo1_phase_lutea: 'Luteal',modulo1_phase_lutea_days: 'Days 18–28',
