    modulo2_l1_h2_1: 'Money isn\'t bad — your relationship with it can be',
    modulo2_l1_h2_2: 'The patterns you inherited without knowing',
    modulo2_l1_h2_3: 'Lesson reflection',
    modulo2_l1_p_1: 'We all have a money story. Some grew up hearing "money doesn\'t grow on trees." Others saw fights over money. Those stories create beliefs that affect how we spend and save.',
    modulo2_l1_p_2: 'Women spend more during the premenstrual and ovulatory phases. It\'s not weakness — it\'s the hormone progesterone increasing our desire to buy.',
