    modulo_video_fallback: 'Votre navigateur ne supporte pas la vidéo.',
    modulo1_l1_h2_1: 'Votre corps n\'est pas une machine — c\'est un cycle',
    modulo1_l1_h2_2: 'Les 4 phases qu\'on ne vous a pas apprises à l\'école',
    modulo1_l1_p_1: 'Chaque mois, votre corps traverse 4 phases qui affectent votre énergie, concentration et humeur. Ce n\'est pas de la caprice — c\'est de la biologie.',
    modulo1_l1_p_2: 'Quand vous comprenez votre cycle, vous pouvez mieux planifier votre semaine, négocier avec plus de confiance et vous reposer sans culpabilité.',
    modulo1_l1_p_3: 'La phase menstruelle (jours 1-5) est votre moment d\'introspection. Votre énergie est basse, mais votre intuition est à son maximum.',
    modulo1_l1_p_4: 'La phase folliculaire (jours 6-13) est quand votre énergie monte. C\'est le moment idéal pour commencer de nouveaux projets.',
    modulo1_l1_p_5: 'La phase ovulatoire (jours 14-16) est votre point le plus haut. Énergie, confiance et communication à leur maximum.',
    modulo1_l1_p_6: 'La phase lutéale (jours 17-28) est une phase de préparation. Votre corps se prépare, et votre énergie diminue progressivement.',
    modulo1_l1_callout_intro_title: '🔬 Ce que vous apprendrez dans ce module',
    modulo1_l1_callout_intro: 'Identifier chaque phase de votre cycle, savoir quel type de travail est idéal pour chaque moment, et créer un système de planification qui s\'adapte à votre corps, pas l\'inverse.',
    modulo1_l1_callout_1: '💡 Fait: Les hormones n\'affectent pas seulement votre utérus — elles affectent votre cerveau, productivité et prise de décision.',
    modulo1_l1_callout_2: '🎯 Action: Notez quand commence votre cycle ce mois-ci et marquez les phases dans votre calendrier.',
    modulo1_l1_callout_3: '💡 Fait: Votre énergie, charisme et capacité de communication sont à leur apogée pendant la phase ovulatoire.',
    modulo1_l1_callout_4: '💡 Fait: La phase lutéale est idéale pour terminer les tâches en attente et organiser les fichiers.',
    modulo1_l1_phase_0_title: '🌑 Phase Menstruelle — Votre temps de repos',
    modulo1_l1_phase_1_title: '🌒 Phase Folliculaire — Votre énergie croissante',
    modulo1_l1_phase_2_title: '🌕 Phase Ovulatoire — Votre moment de pointe',
    modulo1_l1_phase_3_title: '🌘 Phase Lutéale — Votre mode organisateur',
    modulo1_l1_4fases_intro: 'Chaque mois, votre corps traverse ces 4 phases. Cliquez sur chacune pour en savoir plus:',
    modulo1_phase_menstrual: 'Menstruelle',modulo1_phase_menstrual_days: 'Jours 1–5',
    modulo1_phase_folicular: 'Folliculaire',modulo1_phase_folicular_days: 'Jours 6–13',
