    modulo2_l1_h2_2: 'Les schémas que vous avez hérités sans le savoir',
    modulo2_l1_h2_3: 'Réflexion de cette leçon',
    modulo2_l1_p_1: 'Nous avons toutes une histoire avec l\'argent. Certaines ont grandi en entendant "l\'argent ne pousse pas dans les arbres". D\'autres ont vu des disputes pour l\'argent. Ces histoires créent des croyances qui influencent comment nous dépargnons et économisons.',
    modulo2_l1_p_2: 'Les femmes dépensent plus pendant les phases prémenstruelle et ovulatoire. Ce n\'est pas de la faiblesse — c\'est l\'hormone progestérone qui augmente notre envie d\'acheter.',
