    modulo_video_fallback: 'Dein Browser unterstützt kein Video.',
    modulo1_l1_h2_1: 'Dein Körper ist keine Maschine — er ist ein Zyklus',
    modulo1_l1_h2_2: 'Die 4 Phasen, die dir in der Schule nicht beigebracht wurden',
    modulo1_l1_p_1: 'Jeden Monat durchläuft dein Körper 4 Phasen, die deine Energie, Konzentration und Stimmung beeinflussen. Es ist keine Laune — es ist Biologie.',
    modulo1_l1_p_2: 'Wenn du deinen Zyklus verstehst, kannst du deine Woche besser planen, mit mehr Selbstvertrauen verhandeln und ohne schlechtes Gewissen ausruhen.',
    modulo1_l1_p_3: 'Die Menstruationsphase (Tage 1-5) ist dein Moment der Introspektion. Deine Energie ist niedrig, aber deine Intuition ist auf dem Höhepunkt.',
    modulo1_l1_p_4: 'Die Follikelphase (Tage 6-13) ist, wenn deine Energie steigt. Der ideale Moment, um neue Projekte zu starten.',
    modulo1_l1_p_5: 'Die Ovulationsphase (Tage 14-16) ist dein höchster Punkt. Energie, Selbstvertrauen und Kommunikation auf dem Höhepunkt.',
    modulo1_l1_p_6: 'Die Lutealphase (Tage 17-28) ist eine Vorbereitungsphase. Dein Körper bereitet sich vor, und deine Energie nimmt allmählich ab.',
    modulo1_l1_callout_intro_title: '🔬 Was du in diesem Modul lernst',
    modulo1_l1_callout_intro: 'Identifiziere jede Phase deines Zyklus, erfahre welche Art von Arbeit ideal für jeden Moment ist, und erstelle ein Planungssystem das sich deinem Körper anpasst, nicht umgekehrt.',
    modulo1_l1_callout_1: '💡 Fakt: Hormone beeinflussen nicht nur deine Gebärmutter — sie beeinflussen dein Gehirn, Produktivität und Entscheidungsfindung.',
    modulo1_l1_callout_2: '🎯 Aktion: Schreib auf, wann dein Zyklus diesen Monat beginnt, und markiere die Phasen in deinem Kalender.',
    modulo1_l1_callout_3: '💡 Fakt: Deine Energie, dein Charisma und deine Kommunikationsfähigkeit sind während der Ovulationsphase auf dem Höhepunkt.',
    modulo1_l1_callout_4: '💡 Fakt: Die Lutealphase ist ideal, um ausstehende Aufgaben abzuschließen und Dateien zu organisieren.',
    modulo1_l1_phase_0_title: '🌑 Menstruationsphase — Deine Ruhezeit',
    modulo1_l1_phase_1_title: '🌒 Follikelphase — Deine steigende Energie',
    modulo1_l1_phase_2_title: '🌕 Ovulationsphase — Dein Höhepunkt',
    modulo1_l1_phase_3_title: '🌘 Lutealphase — Dein Organisationsmodus',
    modulo1_l1_4fases_intro: 'Jeden Monat durchläuft dein Körper diese 4 Phasen. Klicke auf jede, um sie kennenzulernen:',
    modulo1_phase_menstrual: 'Menstruation',modulo1_phase_menstrual_days: 'Tage 1–5',
