    modulo2_l1_h2_3: 'Reflexion dieser Lektion',
    modulo2_l1_p_1: 'Wir alle haben eine Geschichte mit Geld. Manche sind aufgewachsen mit "Geld wächst nicht auf Bäumen". Andere haben Streit um Geld gesehen. Diese Geschichten schaffen Überzeugungen, die beeinflussen wie wir ausgeben und sparen.',
    modulo2_l1_p_2: 'Frauen geben mehr aus während der prämenstruellen und ovulatorischen Phase. Das ist keine Schwäche — es ist das Hormon Progesteron, das unseren Kaufwunsch steigert.',
