    sp_faq_title_2: 'am häufigsten fragen',
    sp_faq_q1: 'Wie greife ich auf mein Produkt zu?',
    sp_faq_a1: 'Nach deinem Kauf mit Stripe erhältst du eine Bestätigungs-E-Mail. Melde dich im Portal mit E-Mail und Passwort an, und dein Produkt ist sofort im Bereich "Mein Portal" verfügbar.',
    sp_faq_q2: 'Kann ich eine Rückerstattung verlangen?',
    sp_faq_a2: 'Ja, wir bieten eine 30-Tage-Garantie. Wenn du nicht zufrieden bist, schreib uns an admin@yayika.com und wir erstatten 100% ohne Fragen.',
    sp_faq_q3: 'Wie funktioniert die Mitgliedschaft?',
    sp_faq_a3: 'Die Mitgliedschaft gibt dir unbegrenzten Zugang zu allen Produkten, dem interaktiven Portal, den Frauenkreisen und Neuerscheinungen. Du kannst zwischen Semilla, Guerrera oder Diamante wählen.',
    sp_faq_q4: 'Kann ich meine Mitgliedschaft kündigen?',
    sp_faq_a4: 'Ja, du kannst jederzeit über dein Portal kündigen. Es gibt keine Bindung oder Strafen. Dein Zugang bleibt bis zum Ende der bezahlten Zeit erhalten.',
    sp_faq_q5: 'Funktionieren die Produkte auf dem Handy?',
    sp_faq_a5: 'Ja! Yayika ist eine Progressive Web App (PWA), die vom Browser deines Handys funktioniert. Du kannst sie auch als App installieren von Chrome → Menü ⋮ → "Zum Startbildschirm hinzufügen".',
    sp_faq_q6: 'Wie trete ich dem Partnerprogramm bei?',
    sp_faq_a6: 'Besuche unsere Partnerseite zum Registrieren. Du erhältst einen personalisierten Code und verdienst Provisionen bei jedem Verkauf über deinen Link.',
    sp_faq_q7: 'In welchen Sprachen ist es verfügbar?',
    sp_faq_a7: 'Yayika ist auf Spanisch, Englisch, Portugiesisch, Französisch und Deutsch verfügbar. Du kannst die Sprache über den Selector oben auf der Seite ändern.',
